def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    # Count overall actions
    opp_c = 0
    opp_d = 0
    my_d = 0
    for me, opp in history:
        if opp == 'C':
            opp_c += 1
        else:
            opp_d += 1
        if me == 'D':
            my_d += 1

    last_me, last_opp = history[-1]

    # Endgame: defect in the last two rounds
    if n >= 98:
        return 'D'

    # Recent window (last 10 rounds)
    recent_len = min(10, n)
    recent_opp = [h[1] for h in history[-recent_len:]]
    recent_my = [h[0] for h in history[-recent_len:]]
    recent_opp_c = sum(1 for a in recent_opp if a == 'C')
    recent_opp_d = recent_len - recent_opp_c
    recent_my_d = sum(1 for a in recent_my if a == 'D')

    opp_rate = opp_c / n

    # Consecutive opponent defections
    run_d = 0
    for me, opp in reversed(history):
        if opp == 'D':
            run_d += 1
        else:
            break

    # Extremely cooperative opponent: exploit heavily
    if n >= 8 and opp_rate >= 0.95:
        if recent_my_d <= 3 and rng.random() < 0.8:
            return 'D'
        return 'C'

    # Very cooperative opponent
    if n >= 6 and opp_rate > 0.8:
        if recent_opp_d == 0:
            if recent_my_d <= 2 and rng.random() < 0.5:
                return 'D'
            return 'C'
        else:
            if last_opp == 'D':
                if run_d >= 3 and rng.random() < 0.3:
                    return 'C'
                if opp_rate > 0.9 and recent_opp_d <= 1:
                    return 'C'
                return 'D'
            else:
                if recent_my_d <= 1 and rng.random() < 0.3:
                    return 'D'
                return 'C'

    # Moderately cooperative opponent
    if opp_rate >= 0.4:
        if last_opp == 'D':
            if run_d >= 3 and rng.random() < 0.3:
                return 'C'
            if opp_rate > 0.8 and recent_opp_d <= 1:
                return 'C'
            return 'D'
        else:
            if opp_rate > 0.6 and recent_my_d <= 1 and rng.random() < 0.1:
                return 'D'
            return 'C'

    # Mostly defecting opponent
    if last_opp == 'C':
        return 'C'
    else:
        if run_d >= 3 and rng.random() < 0.1:
            return 'C'
        if rng.random() < 0.05:
            return 'C'
        return 'D'
